-- ----------------------------
-- Table structure for biz_attribute
-- ----------------------------
DROP TABLE IF EXISTS `biz_attribute`;
CREATE TABLE `biz_attribute`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '属性ID，示例：1',
  `attr_name` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '属性名称，示例：颜色、大小、品级、产地',
  `attr_type` tinyint NOT NULL DEFAULT 1 COMMENT '属性类型：1-SPU属性（关键属性），2-SKU属性（销售属性），示例：2',
  `input_type` tinyint NOT NULL DEFAULT 1 COMMENT '输入类型：1-单选，2-多选，3-手填文本，示例：1',
  `is_required` tinyint NOT NULL DEFAULT 0 COMMENT '是否必填：0-否，1-是，示例：1',
  `is_searchable` tinyint NOT NULL DEFAULT 1 COMMENT '是否支持前台筛选：0-否，1-是，示例：1',
  `sort_order` int NOT NULL DEFAULT 0 COMMENT '排序（越小越靠前），示例：10',
  `status` tinyint NOT NULL DEFAULT 1 COMMENT '状态：0-禁用，1-启用，示例：1',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_attr_type`(`attr_type`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 13 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '属性定义表' ROW_FORMAT = Dynamic;

