-- Records of biz_attribute
-- ----------------------------

-- ----------------------------
-- Table structure for biz_attribute_value
-- ----------------------------
DROP TABLE IF EXISTS `biz_attribute_value`;
CREATE TABLE `biz_attribute_value`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '属性值ID，示例：10',
  `attr_id` bigint NOT NULL COMMENT '所属属性ID（关联biz_attribute.id），示例：4（颜色属性）',
  `value` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '属性值名称，示例：红色、大果、一级',
  `sort_order` int NOT NULL DEFAULT 0 COMMENT '排序，示例：1',
  `extra_json` json NULL COMMENT '扩展信息，例如关联图片或重量范围，示例：{\"weight_range\":\"70-80mm\", \"image\":\"https://example.com/red.jpg\"}',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_attr_value`(`attr_id`, `value`) USING BTREE,
  INDEX `idx_attr_id`(`attr_id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 32 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '属性值表' ROW_FORMAT = Dynamic;

