INSERT INTO `biz_product` VALUES (1, 1, 1, '百色无硫大红八角', '自家果园足干无硫 香味浓郁', '/show/product/1781324955459.png', '[\"/show/product/1781324964751.png\", \"/show/product/1781324969434.png\", \"/show/product/1781324973761.png\", \"/show/product/1781324978773.png\"]', '<p>产地：广西百色田阳</p><p>工艺：自然晾晒，无硫烘干</p><p>等级：足干大红八角</p>', '广西百色市田阳区', 1, '足干9.5成', '传统种植 自然晾晒', 1, 0, NULL, NULL, NULL, NULL, NULL, 0, '2026-04-14 10:44:47', '2026-04-14 10:44:47');
INSERT INTO `biz_product` VALUES (2, 1, 1, '测试', '1', '/show/product/1781774462729.png', '[\"/show/product/1777281519831.png\", \"/show/product/1777281531049.png\", \"/show/product/1781774457854.png\"]', '1', NULL, 1, 'q', 'q', 0, 0, NULL, '2026-06-18 17:20:45', '2026-06-25 00:00:00', '2026-06-30', NULL, 0, '2026-04-27 17:19:37', '2026-04-27 17:19:37');
INSERT INTO `biz_product` VALUES (3, 1, 2, '广西百色正宗沃柑 新鲜当季蜜柑桔子现摘水果 新鲜当季广西百色正宗沃柑 新鲜当季蜜柑桔子现摘水果 新鲜当季', '皮薄多汁 甜度高 新鲜现摘 果园直发', '/show/product/1781324906076.png', '[\"/show/product/1781324937016.png\", \"/show/product/1781774422454.png\"]', '<p>产地：广西南宁武鸣</p><p>品种：沃柑（以色列引进改良品种）</p><p>特点：皮薄易剥、果肉细嫩、汁多味甜、无渣</p><p>规格：3斤/5斤/10斤可选</p><p>售后：坏果包赔，收到有坏果拍照联系客服</p>', '广西南宁市武鸣区', 1, NULL, '山地种植 自然成熟 不催熟不打蜡', 1, 0, NULL, NULL, NULL, NULL, NULL, 0, '2026-06-11 20:49:46', '2026-06-11 19:59:17');
INSERT INTO `biz_product` VALUES (4, 2, 2, '百色台农芒果', '香甜软糯 核薄肉厚 现摘现发 新鲜到家', '/show/product/1781324790300.png', '[\"/show/product/1781324811315.jpg\", \"/show/product/1781324823112.jpg\", \"/show/product/1781324828748.jpg\", \"/show/product/1781324882916.jpg\", \"/show/product/1781774408986.png\"]', '<p>产地：广西百色田阳</p><p>品种：台农一号芒</p><p>特点：果肉金黄、香甜软糯、核薄如纸、纤维极少</p><p>规格：3斤/5斤/10斤可选</p><p>提示：收到后如未全熟，放2-3天软了更甜</p><p>售后：坏果包赔，拍照联系客服秒退款</p>', '广西百色市田阳区', 1, NULL, '山地种植 自然成熟 不催熟', 1, 0, NULL, '2026-06-15 19:12:17', '2026-06-25 15:35:36', '2026-06-30', '春季', 0, '2026-06-15 19:09:48', '2026-06-11 19:59:17');
